81	  const [searchFilter, setSearchFilter] = useState('');
82	
83	  const token = localStorage.getItem("accessToken");
84	  // All recognition traffic goes through the Node backend - never FastAPI directly.
85	  const NODE_SERVER_URL = `${API_BASE_URL}/api/security/logs`;
