87	  // V-Patrol is a monitoring post: it records access AUDIT events only and must
88	  // never toggle clock-in/out (that belongs to the Gate Scanner's scan endpoint).
89	  const ACCESS_EVENT_URL = `${API_BASE_URL}/api/facial-recognition/access-event`;
