1	// Raspberry Pi Camera Module 3 — gate camera node configuration.
2	// URLs come from Vite env (VITE_PI_CAMERA_STREAM_URL / VITE_PI_CAMERA_SNAPSHOT_URL)
3	// with demo-network fallbacks so the kiosk works out of the box.
4	
5	export const PI_CAMERA_STREAM_URL =
6	  import.meta.env.VITE_PI_CAMERA_STREAM_URL || "http://172.20.10.4:8081/video_feed";
7	
8	export const PI_CAMERA_SNAPSHOT_URL =
9	  import.meta.env.VITE_PI_CAMERA_SNAPSHOT_URL || "http://172.20.10.4:8081/snapshot";
10	
11	export const CAMERA_SOURCES = {
12	  PI: "pi",
13	  WEBCAM: "webcam",
14	};
15	
16	export const CAMERA_STATUS_MESSAGES = {
17	  PI_CONNECTED: "Pi Gate Camera connected",
18	  PI_UNAVAILABLE: "Pi Camera unavailable — using laptop webcam fallback",
19	  WEBCAM_ACTIVE: "Laptop webcam active",
20	};
21	
22	// While the Pi is known-unavailable, don't re-probe it on every recognition
23	// cycle — cache the failure and only allow a fresh probe after this cooldown.
24	// Laptop-webcam recognition is never blocked by a pending Pi timeout.
25	export const PI_UNAVAILABLE_COOLDOWN_MS = 10000;
26	
27	let piUnavailableUntil = 0;
28	
29	/** Record a Pi failure so probes are throttled for the cooldown window. */
30	export function markPiUnavailable(now = Date.now()) {
31	  piUnavailableUntil = now + PI_UNAVAILABLE_COOLDOWN_MS;
32	}
33	
34	/** True while a recent Pi failure is cached (probing would be wasted time). */
35	export function isPiInCooldown(now = Date.now()) {
36	  return now < piUnavailableUntil;
37	}
38	
39	/** Clear the cached Pi failure (tests / explicit user retry). */
40	export function resetPiAvailabilityCache() {
41	  piUnavailableUntil = 0;
42	}
43	
44	/**
45	 * Cooldown-aware reachability check: while a recent Pi failure is cached,
46	 * returns false immediately WITHOUT a network probe, so scanner pages fall
47	 * back to the laptop webcam fast instead of waiting out a Pi timeout.
48	 */
49	export async function isPiCameraReachableCached(now = Date.now()) {
50	  if (isPiInCooldown(now)) return false;
51	  const reachable = await isPiCameraReachable();
52	  if (!reachable) markPiUnavailable();
53	  else piUnavailableUntil = 0;
54	  return reachable;
55	}
56	
57	/**
58	 * Probe the Pi snapshot endpoint to decide if the gate camera is reachable.
59	 * Any network error, CORS block, or timeout counts as unreachable so the
